   991→    /// Handle a `BlobsByRange` request from the peer.
   992→    fn handle_blobs_by_range_request_inner(
   993→        &self,
   994→        peer_id: PeerId,
   995→        inbound_request_id: InboundRequestId,
   996→        req: BlobsByRangeRequest,
   997→    ) -> Result<(), (RpcErrorResponse, &'static str)> {
   998→        debug!(
   999→            ?peer_id,
  1000→            count = req.count,
  1001→            start_slot = req.start_slot,
  1002→            "Received BlobsByRange Request"
  1003→        );
  1004→
  1005→        let request_start_slot = Slot::from(req.start_slot);
  1006→
  1007→        let data_availability_boundary_slot = match self.chain.data_availability_boundary() {
  1008→            Some(boundary) => boundary.start_slot(T::EthSpec::slots_per_epoch()),
  1009→            None => {
  1010→                debug!("Deneb fork is disabled");
  1011→                return Err((RpcErrorResponse::InvalidRequest, "Deneb fork is disabled"));
  1012→            }
  1013→        };
  1014→
  1015→        let oldest_blob_slot = self
  1016→            .chain
  1017→            .store
  1018→            .get_blob_info()
  1019→            .oldest_blob_slot
  1020→            .unwrap_or(data_availability_boundary_slot);
  1021→        if request_start_slot < oldest_blob_slot {
  1022→            debug!(
  1023→                %request_start_slot,
  1024→                %oldest_blob_slot,
  1025→                %data_availability_boundary_slot,
  1026→                "Range request start slot is older than data availability boundary."
  1027→            );
  1028→
  1029→            return if data_availability_boundary_slot < oldest_blob_slot {
  1030→                Err((
  1031→                    RpcErrorResponse::ResourceUnavailable,
  1032→                    "blobs pruned within boundary",
  1033→                ))
  1034→            } else {
  1035→                Err((
  1036→                    RpcErrorResponse::InvalidRequest,
  1037→                    "Req outside availability period",
  1038→                ))
  1039→            };
  1040→        }
  1041→
  1042→        let block_roots =
  1043→            self.get_block_roots_for_slot_range(req.start_slot, req.count, "BlobsByRange")?;
  1044→
  1045→        let current_slot = self
  1046→            .chain
  1047→            .slot()
  1048→            .unwrap_or_else(|_| self.chain.slot_clock.genesis_slot());
  1049→
  1050→        let log_results = |peer_id, req: BlobsByRangeRequest, blobs_sent| {
  1051→            debug!(
  1052→                %peer_id,
  1053→                start_slot = req.start_slot,
  1054→                %current_slot,
  1055→                requested = req.count,
  1056→                returned = blobs_sent,
  1057→                "BlobsByRange outgoing response processed"
  1058→            );
  1059→        };
  1060→
  1061→        let mut blobs_sent = 0;
  1062→
  1063→        for root in block_roots {
  1064→            match self.chain.get_blobs(&root) {
  1065→                Ok(blob_sidecar_list) => {
  1066→                    for blob_sidecar in blob_sidecar_list.iter() {
  1067→                        // Due to skip slots, blobs could be out of the range, we ensure they
  1068→                        // are in the range before sending
  1069→                        if blob_sidecar.slot() >= request_start_slot
  1070→                            && blob_sidecar.slot() < request_start_slot + req.count
  1071→                        {
  1072→                            blobs_sent += 1;
  1073→                            self.send_network_message(NetworkMessage::SendResponse {
  1074→                                peer_id,
  1075→                                inbound_request_id,
  1076→                                response: Response::BlobsByRange(Some(blob_sidecar.clone())),
  1077→                            });
  1078→                        }
  1079→                    }
  1080→                }
  1081→                Err(e) => {
  1082→                    error!(
  1083→                        request = ?req,
  1084→                        %peer_id,
  1085→                        block_root = ?root,
  1086→                        error = ?e,
  1087→                        "Error fetching blobs block root"
  1088→                    );
  1089→                    log_results(peer_id, req, blobs_sent);
  1090→
  1091→                    return Err((
  1092→                        RpcErrorResponse::ServerError,
  1093→                        "No blobs and failed fetching corresponding block",
  1094→                    ));
  1095→                }
  1096→            }
  1097→        }
  1098→        log_results(peer_id, req, blobs_sent);
  1099→
  1100→        Ok(())
  1101→    }
  1102→
  1103→    /// Handle a `DataColumnsByRange` request from the peer.
  1104→    #[instrument(
  1105→        name = SPAN_HANDLE_DATA_COLUMNS_BY_RANGE_REQUEST,
  1106→        parent = None,
  1107→        skip_all,
  1108→        level = "debug",
  1109→        fields(peer_id = %peer_id, non_custody_indices = tracing::field::Empty, client = tracing::field::Empty)
  1110→    )]
  1111→    pub fn handle_data_columns_by_range_request(
  1112→        &self,
  1113→        peer_id: PeerId,
  1114→        inbound_request_id: InboundRequestId,
  1115→        req: DataColumnsByRangeRequest,
  1116→    ) {
  1117→        let epoch = Slot::new(req.start_slot).epoch(T::EthSpec::slots_per_epoch());
  1118→        self.record_data_column_request_in_span(
  1119→            &peer_id,
  1120→            &req.columns,
  1121→            Some(epoch),
  1122→            Span::current(),
  1123→        );
  1124→
  1125→        self.terminate_response_stream(
  1126→            peer_id,
  1127→            inbound_request_id,
  1128→            self.handle_data_columns_by_range_request_inner(peer_id, inbound_request_id, req),
  1129→            Response::DataColumnsByRange,
  1130→        );
  1131→    }
  1132→
  1133→    /// Handle a `DataColumnsByRange` request from the peer.
  1134→    fn handle_data_columns_by_range_request_inner(
  1135→        &self,
  1136→        peer_id: PeerId,
  1137→        inbound_request_id: InboundRequestId,
  1138→        req: DataColumnsByRangeRequest,
  1139→    ) -> Result<(), (RpcErrorResponse, &'static str)> {
  1140→        debug!(
  1141→            %peer_id,
  1142→            count = req.count,
  1143→            start_slot = req.start_slot,
  1144→            "Received DataColumnsByRange Request"
  1145→        );
  1146→
  1147→        // Should not send more than max request data columns
  1148→        if req.max_requested::<T::EthSpec>() > self.chain.spec.max_request_data_column_sidecars {
  1149→            return Err((
  1150→                RpcErrorResponse::InvalidRequest,
  1151→                "Request exceeded `MAX_REQUEST_BLOBS_SIDECARS`",
  1152→            ));
  1153→        }
  1154→
  1155→        let request_start_slot = Slot::from(req.start_slot);
  1156→
  1157→        let data_availability_boundary_slot = match self.chain.data_availability_boundary() {
  1158→            Some(boundary) => boundary.start_slot(T::EthSpec::slots_per_epoch()),
  1159→            None => {
  1160→                debug!("Deneb fork is disabled");
  1161→                return Err((RpcErrorResponse::InvalidRequest, "Deneb fork is disabled"));
  1162→            }
  1163→        };
  1164→
  1165→        let oldest_data_column_slot = self
  1166→            .chain
  1167→            .store
  1168→            .get_data_column_info()
  1169→            .oldest_data_column_slot
  1170→            .unwrap_or(data_availability_boundary_slot);
  1171→
  1172→        if request_start_slot < oldest_data_column_slot {
  1173→            debug!(
  1174→                %request_start_slot,
  1175→                %oldest_data_column_slot,
  1176→                %data_availability_boundary_slot,
  1177→                "Range request start slot is older than data availability boundary."
  1178→            );
  1179→
  1180→            return if data_availability_boundary_slot < oldest_data_column_slot {
  1181→                Err((
  1182→                    RpcErrorResponse::ResourceUnavailable,
  1183→                    "blobs pruned within boundary",
  1184→                ))
  1185→            } else {
  1186→                Err((
  1187→                    RpcErrorResponse::InvalidRequest,
  1188→                    "Req outside availability period",
  1189→                ))
  1190→            };
  1191→        }
  1192→
  1193→        let block_roots =
  1194→            self.get_block_roots_for_slot_range(req.start_slot, req.count, "DataColumnsByRange")?;
  1195→        let mut data_columns_sent = 0;
  1196→
  1197→        // Only attempt lookups for columns the node has advertised and is responsible for maintaining custody of.
  1198→        let request_start_epoch = request_start_slot.epoch(T::EthSpec::slots_per_epoch());
  1199→        let available_columns = self
  1200→            .chain
  1201→            .custody_columns_for_epoch(Some(request_start_epoch));
  1202→
  1203→        let indices_to_retrieve = req
  1204→            .columns
  1205→            .iter()
  1206→            .copied()
  1207→            .filter(|c| available_columns.contains(c))
  1208→            .collect::<Vec<_>>();
  1209→
  1210→        for root in block_roots {
  1211→            for index in &indices_to_retrieve {
  1212→                match self.chain.get_data_column(&root, index) {
  1213→                    Ok(Some(data_column_sidecar)) => {
