  1220→                            self.send_network_message(NetworkMessage::SendResponse {
  1221→                                peer_id,
  1222→                                inbound_request_id,
  1223→                                response: Response::DataColumnsByRange(Some(
  1224→                                    data_column_sidecar.clone(),
  1225→                                )),
  1226→                            });
  1227→                        }
  1228→                    }
  1229→                    Ok(None) => {} // no-op
  1230→                    Err(e) => {
  1231→                        error!(
  1232→                            request = ?req,
  1233→                            %peer_id,
  1234→                            block_root = ?root,
  1235→                            error = ?e,
  1236→                            "Error fetching data columns block root"
  1237→                        );
  1238→                        return Err((
  1239→                            RpcErrorResponse::ServerError,
  1240→                            "No data columns and failed fetching corresponding block",
  1241→                        ));
  1242→                    }
  1243→                }
  1244→            }
  1245→        }
  1246→
  1247→        let current_slot = self
  1248→            .chain
  1249→            .slot()
  1250→            .unwrap_or_else(|_| self.chain.slot_clock.genesis_slot());
  1251→
  1252→        debug!(
  1253→            %peer_id,
  1254→            start_slot = req.start_slot,
  1255→            %current_slot,
  1256→            requested = req.count,
  1257→            returned = data_columns_sent,
  1258→            "DataColumnsByRange Response processed"
  1259→        );
  1260→
  1261→        Ok(())
  1262→    }
