  1319→                .custody_context()
  1320→                .custody_columns_for_epoch(epoch_opt, &self.chain.spec);
  1321→            requested_indices
  1322→                .iter()
  1323→                .filter(|subnet_id| !custody_columns.contains(subnet_id))
  1324→                .collect::<Vec<_>>()
